def get_bills(
    self,
    start,
    end,
    first_crawl,
    first_loop,
    page_token={"fba_token": None, "existing_posted_after": None},
    sync_job_id=None,
):
    if first_loop:
        self.bills_by_id = {}
        if page_token["fba_token"]:
            # next tokens expire super quickly
            # so if the crawl has died and picked up again, use the same date params but clear the token
            page_token["fba_token"] = None
    page_bills_by_id = {}
    credentials = self.get_sp_api_creds()
    marketplaces = self.get_marketplaces()
    bills = []
    finances_client = Finances(
        credentials=credentials, marketplace=Marketplaces[marketplaces[0]]
    )
    furthest_lookback = now() - timedelta(days=730)  # bugs if longer
    fba_start_time = max(start, furthest_lookback)
    existing_posted_after_str = page_token["existing_posted_after"]
    if existing_posted_after_str:
        existing_posted_after_dt = str_to_dt(existing_posted_after_str)
        fba_start_time = max(existing_posted_after_dt, furthest_lookback)
    posted_after_date = fba_start_time.strftime("%Y-%m-%d")

    # Can get up to six months but takes so long so we never move to another page
    one_day_ahead = fba_start_time + timedelta(days=1)
    three_minutes_ago = end - timedelta(minutes=3)
    # use end instead of now so that it doesn't move up
    # we have crawl_start_overlap_minutes to handle any overlap needed
    max_report_end = min(one_day_ahead, three_minutes_ago)
    fba_end_time = min(end, max_report_end)
    existing_posted_before_str = page_token.get("existing_posted_before")
    if existing_posted_before_str:
        existing_posted_before_dt = str_to_dt(existing_posted_before_str)
        fba_end_time = existing_posted_before_dt
    params = {
        "PostedAfter": dt_to_str(fba_start_time),
        "PostedBefore": dt_to_str(fba_end_time),
    }
    if page_token["fba_token"]:
        params["NextToken"] = page_token["fba_token"]
    try:
        response = get_financial_events(self, finances_client, **params)
    except InvalidCredentialsException as e:
        raise e
    except PermissionsException as e:
        raise e
    except Exception as e:
        raise PokedexException(
            f"Error getting financial events: {e}", 400, origin="integration"
        )
    fba_next_token = response.next_token
    next_token = None
    if fba_next_token:
        next_token = {
            "fba_token": fba_next_token,
            "existing_posted_after": dt_to_str(fba_start_time),
            "existing_posted_before": dt_to_str(fba_end_time),
        }
    elif fba_end_time < three_minutes_ago:
        next_token = {
            "fba_token": None,
            "existing_posted_after": dt_to_str(fba_end_time),
        }

